APP_JS = r'''
(function(){
  "use strict";

  var state = {
    products: [],
    quotes: [],
    settings: {},
    items: [],
    selectedProduct: null,
    editingProductId: null,
    currentNumber: "",
    saved: false,
    saving: false,
    savingSettings: false,
    savingProduct: false,
  };

  var money = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });
  var dateFmt = new Intl.DateTimeFormat("pt-BR");

  function $(id){ return document.getElementById(id); }

  function escapeHTML(value){
    return String(value == null ? "" : value).replace(/[&<>"']/g, function(c){
      return { "&":"&amp;", "<":"&lt;", ">":"&gt;", "\"":"&quot;", "'":"&#39;" }[c];
    });
  }

  function todayISO(){ return new Date().toISOString().slice(0, 10); }

  function addDaysISO(days){
    var d = new Date();
    d.setHours(12, 0, 0, 0);
    d.setDate(d.getDate() + Number(days || 0));
    return d.toISOString().slice(0, 10);
  }

  function formatDateBR(value){
    if(!value) return "-";
    return dateFmt.format(new Date(String(value).slice(0, 10) + "T12:00:00"));
  }

  function quoteNumber(sequence){
    return "ORC-" + todayISO().replaceAll("-", "") + "-" + String(sequence + 1).padStart(3, "0");
  }

  function makeId(){
    return Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 10);
  }

  function quantityLabel(item){
    if(item.unit === "kg"){
      return item.quantity.toLocaleString("pt-BR", { maximumFractionDigits: 3 }) + " kg";
    }
    return item.quantity.toLocaleString("pt-BR") + " un.";
  }

  function unitSuffix(unit){
    if(unit === "kg") return "/kg";
    if(unit === "cento") return "/cento";
    return "/un.";
  }

  function priceLabelProduct(p){
    return money.format(p.priceCents / 100) + " " + unitSuffix(p.unit);
  }

  function toast(message, type){
    var container = $("toast-container");
    var el = document.createElement("div");
    el.className = "toast toast-" + (type || "success");
    el.textContent = message;
    container.appendChild(el);
    setTimeout(function(){ el.remove(); }, 3500);
  }

  async function postAction(payload){
    var res = await fetch("/api/data", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    var data = await res.json();
    if(!res.ok) throw new Error(data.error || "Não foi possível salvar.");
    return data;
  }

  // ------------------------------------------------------------------
  // Carregamento inicial
  // ------------------------------------------------------------------

  async function loadData(){
    try {
      var res = await fetch("/api/data", { cache: "no-store" });
      var data = await res.json();
      if(!res.ok) throw new Error(data.error);
      state.products = data.products;
      state.quotes = data.quotes;
      state.settings = data.settings;
      if(!state.currentNumber) state.currentNumber = quoteNumber(data.quotes.length);
      applySettingsToForm();
      renderProductsTab();
      renderHistoryTab();
      renderQuoteRight();
      $("skeleton").classList.add("hidden");
      $("app-root").classList.remove("hidden");
    } catch(e){
      toast((e && e.message) || "Não foi possível carregar os dados.", "error");
    }
  }

  function applySettingsToForm(){
    var keys = ["company_name","trade_name","cnpj","phone","email","address","validity_days","deposit_percent","lead_time_days","payment_note"];
    keys.forEach(function(key){
      var el = $("set-" + key);
      if(el) el.value = state.settings[key] || "";
    });
    var validityDays = Number(state.settings.validity_days || 5);
    $("validity-label").textContent = "Validade do orçamento (" + validityDays + " dias)";
    $("input-validity").value = formatDateBR(addDaysISO(validityDays));
  }

  // ------------------------------------------------------------------
  // Abas
  // ------------------------------------------------------------------

  function switchTab(tab){
    document.querySelectorAll(".tab-btn").forEach(function(btn){
      btn.classList.toggle("active", btn.dataset.tab === tab);
    });
    document.querySelectorAll(".tab-panel").forEach(function(panel){
      panel.classList.toggle("hidden", panel.dataset.tab !== tab);
    });
  }

  // ------------------------------------------------------------------
  // Combobox de produtos
  // ------------------------------------------------------------------

  function closeDropdown(){
    var dd = $("product-dropdown");
    dd.classList.add("hidden");
    dd.innerHTML = "";
  }

  function filteredProductOptions(query){
    var q = (query || "").trim().toLocaleLowerCase("pt-BR");
    var options = state.products.filter(function(p){ return p.active; });
    if(q){
      options = options.filter(function(p){
        var label = (p.name + " " + p.category + " " + priceLabelProduct(p)).toLocaleLowerCase("pt-BR");
        return label.indexOf(q) !== -1;
      });
    }
    return options.slice(0, 15);
  }

  function renderDropdown(list){
    var dd = $("product-dropdown");
    if(!list.length){
      dd.innerHTML = '<div class="combobox-empty">Nenhum produto encontrado.</div>';
    } else {
      dd.innerHTML = list.map(function(p){
        return '<div class="combobox-item" onclick="app.selectProductOption(' + p.id + ')">' +
          '<span class="opt-name">' + escapeHTML(p.name) + '</span>' +
          '<span class="opt-meta">' + escapeHTML(p.category) + ' · ' + escapeHTML(priceLabelProduct(p)) + '</span>' +
        '</div>';
      }).join("");
    }
    dd.classList.remove("hidden");
  }

  function onProductSearchInput(){
    state.selectedProduct = null;
    renderProductHint();
    renderDropdown(filteredProductOptions($("product-search").value));
  }

  function selectProductOption(productId){
    var product = state.products.find(function(p){ return p.id === productId; });
    if(!product) return;
    state.selectedProduct = product;
    $("product-search").value = product.name + " · " + priceLabelProduct(product);
    closeDropdown();
    renderProductHint();
    $("input-quantity").focus();
  }

  function renderProductHint(){
    var hint = $("product-hint");
    var p = state.selectedProduct;
    if(!p){ hint.innerHTML = ""; return; }
    var parts = ['<span class="badge badge-outline">' + escapeHTML(priceLabelProduct(p)) + '</span>'];
    if(p.minimumQuantity > 0){
      parts.push('<span>Mínimo: ' + p.minimumQuantity + (p.unit === "kg" ? " kg" : " unidades") + '</span>');
    }
    if(p.description){
      parts.push('<span>· ' + escapeHTML(p.description) + '</span>');
    }
    hint.innerHTML = parts.join("");
    $("quantity-label").textContent = p.unit === "kg" ? "Quantidade (kg)" : "Quantidade (un.)";
    $("input-quantity").placeholder = p.unit === "kg" ? "Ex.: 2,5" : "Ex.: 75";
  }

  // ------------------------------------------------------------------
  // Itens do orçamento
  // ------------------------------------------------------------------

  function addItem(){
    var product = state.selectedProduct;
    var raw = $("input-quantity").value;
    var parsedQuantity = Number(String(raw).replace(",", "."));
    if(!product){ toast("Escolha um produto.", "error"); return; }
    if(!parsedQuantity || parsedQuantity <= 0){ toast("Informe uma quantidade válida.", "error"); return; }
    if(product.minimumQuantity && parsedQuantity < product.minimumQuantity){
      toast("A quantidade mínima para este item é " + product.minimumQuantity + (product.unit === "kg" ? " kg" : " unidades") + ".", "error");
      return;
    }
    var totalCents = product.unit === "cento"
      ? Math.round(product.priceCents * parsedQuantity / 100)
      : Math.round(product.priceCents * parsedQuantity);
    state.items.push({
      id: makeId(),
      productId: product.id,
      productName: product.name,
      unit: product.unit,
      quantity: parsedQuantity,
      unitPriceCents: product.priceCents,
      totalCents: totalCents,
    });
    state.selectedProduct = null;
    $("product-search").value = "";
    $("input-quantity").value = "";
    $("product-hint").innerHTML = "";
    markChanged();
    renderQuoteRight();
    toast(product.name + " adicionado.", "success");
  }

  function removeItem(id){
    state.items = state.items.filter(function(item){ return item.id !== id; });
    markChanged();
    renderQuoteRight();
  }

  function markChanged(){
    state.saved = false;
    updateSaveButtonState();
  }

  function updateSaveButtonState(){
    var btn = $("btn-save");
    btn.disabled = state.saving || state.saved;
    if(state.saving){ btn.textContent = "Salvando..."; }
    else if(state.saved){ btn.textContent = "✓ Orçamento salvo"; }
    else { btn.textContent = "💾 Salvar orçamento"; }
  }

  function buildItemsTableHTML(){
    if(!state.items.length){
      return '<div class="empty-inline">' +
        '<p class="empty-title">Nenhum produto adicionado</p>' +
        '<p class="empty-text">Busque um item acima e informe a quantidade desejada.</p>' +
      '</div>';
    }
    var rows = state.items.map(function(item){
      return '<tr>' +
        '<td class="cell-strong">' + escapeHTML(item.productName) + '</td>' +
        '<td>' + escapeHTML(quantityLabel(item)) + '</td>' +
        '<td>' + escapeHTML(money.format(item.unitPriceCents / 100) + " " + unitSuffix(item.unit)) + '</td>' +
        '<td class="ta-right cell-strong">' + escapeHTML(money.format(item.totalCents / 100)) + '</td>' +
        '<td class="ta-right"><button class="icon-btn danger" title="Remover" onclick="app.removeItem(\'' + item.id + '\')">✕</button></td>' +
      '</tr>';
    }).join("");
    return '<table><thead><tr><th>Produto</th><th>Quantidade</th><th>Preço-base</th><th class="ta-right">Subtotal</th><th></th></tr></thead>' +
      '<tbody>' + rows + '</tbody></table>';
  }

  function currentSubtotalCents(){
    return state.items.reduce(function(total, item){ return total + item.totalCents; }, 0);
  }

  function buildPreviewHTML(){
    var subtotalCents = currentSubtotalCents();
    var depositPercent = Number(state.settings.deposit_percent || 50);
    var depositCents = Math.round(subtotalCents * depositPercent / 100);
    var validityDays = Number(state.settings.validity_days || 5);
    var validUntil = addDaysISO(validityDays);

    var customerName = $("input-customer-name").value;
    var customerPhone = $("input-customer-phone").value;
    var eventDate = $("input-event-date").value;
    var notes = $("input-notes").value;

    var rows = state.items.length ? state.items.map(function(item){
      return '<tr>' +
        '<td>' + escapeHTML(item.productName) + '</td>' +
        '<td>' + escapeHTML(quantityLabel(item)) + '</td>' +
        '<td class="doc-item-total">' + escapeHTML(money.format(item.totalCents / 100)) + '</td>' +
      '</tr>';
    }).join("") : '<tr><td colspan="3" class="doc-empty">Os produtos adicionados aparecerão aqui.</td></tr>';

    var notesBlock = notes ? (
      '<div class="doc-notes"><p class="document-label">Observações</p><p>' +
      escapeHTML(notes).replaceAll("\n", "<br/>") + '</p></div>'
    ) : "";

    $("quote-preview").innerHTML =
      '<div class="stripe"></div>' +
      '<div class="doc-body">' +
        '<header class="doc-header">' +
          '<img src="data:image/png;base64,' + window.__LOGO_B64__ + '" alt="Panificadora Dreon" class="doc-logo" />' +
          '<div class="doc-head-right">' +
            '<p class="doc-kind">Orçamento</p>' +
            '<p class="doc-number">' + escapeHTML(state.currentNumber) + '</p>' +
            '<p class="doc-issued">Emitido em ' + escapeHTML(formatDateBR(todayISO())) + '</p>' +
          '</div>' +
        '</header>' +
        '<div class="doc-parties">' +
          '<div>' +
            '<p class="document-label">Cliente</p>' +
            '<p class="doc-customer-name">' + (escapeHTML(customerName) || "Nome do cliente") + '</p>' +
            '<p class="doc-muted">' + (escapeHTML(customerPhone) || "Telefone não informado") + '</p>' +
          '</div>' +
          '<div class="doc-right">' +
            '<p class="document-label">Evento / retirada</p>' +
            '<p class="doc-strong">' + (eventDate ? escapeHTML(formatDateBR(eventDate)) : "A combinar") + '</p>' +
            '<p class="doc-muted">Válido até ' + escapeHTML(formatDateBR(validUntil)) + '</p>' +
          '</div>' +
        '</div>' +
        '<div class="doc-items"><table><thead><tr><th>Item</th><th>Qtd.</th><th class="ta-right">Valor</th></tr></thead>' +
          '<tbody>' + rows + '</tbody></table></div>' +
        '<div class="doc-totals">' +
          '<div class="doc-total-row"><span>Total do orçamento</span><strong>' + escapeHTML(money.format(subtotalCents / 100)) + '</strong></div>' +
          '<div class="doc-deposit-row"><span>Sinal de ' + depositPercent + '%</span><strong>' + escapeHTML(money.format(depositCents / 100)) + '</strong></div>' +
        '</div>' +
        notesBlock +
        '<div class="doc-payment">' +
          '<strong>Confirmação da encomenda</strong>' +
          '<p>' + escapeHTML(state.settings.payment_note || "") + '</p>' +
          '<p class="doc-lead">Pedidos para eventos devem ser feitos com no mínimo ' + escapeHTML(state.settings.lead_time_days || "2") + ' dias de antecedência.</p>' +
        '</div>' +
        '<footer class="doc-footer">' +
          '<p class="doc-company">' + escapeHTML(state.settings.company_name || "") + ' · CNPJ ' + escapeHTML(state.settings.cnpj || "") + '</p>' +
          '<p>' + escapeHTML(state.settings.address || "") + '</p>' +
          '<p>' + escapeHTML(state.settings.phone || "") + ' · ' + escapeHTML(state.settings.email || "") + '</p>' +
        '</footer>' +
      '</div>';
  }

  function renderQuoteRight(){
    $("items-table-wrap").innerHTML = buildItemsTableHTML();
    $("current-number-badge").textContent = state.currentNumber;
    var hasItems = state.items.length > 0;
    $("btn-print").disabled = !hasItems;
    $("btn-copy").disabled = !hasItems;
    $("btn-whatsapp").disabled = !hasItems;
    updateSaveButtonState();
    buildPreviewHTML();
  }

  function resetQuote(){
    $("input-customer-name").value = "";
    $("input-customer-phone").value = "";
    $("input-event-date").value = "";
    $("input-notes").value = "";
    state.items = [];
    state.saved = false;
    state.currentNumber = quoteNumber(state.quotes.length);
    renderQuoteRight();
  }

  async function saveQuote(){
    var customerName = $("input-customer-name").value.trim();
    if(!customerName){ toast("Informe o nome do cliente.", "error"); return; }
    if(!state.items.length){ toast("Adicione pelo menos um item.", "error"); return; }

    state.saving = true;
    updateSaveButtonState();
    try {
      var subtotalCents = currentSubtotalCents();
      var depositPercent = Number(state.settings.deposit_percent || 50);
      var validityDays = Number(state.settings.validity_days || 5);
      var quote = {
        id: makeId(),
        quoteNumber: state.currentNumber,
        customerName: customerName,
        customerPhone: $("input-customer-phone").value,
        eventDate: $("input-event-date").value || null,
        validUntil: addDaysISO(validityDays),
        notes: $("input-notes").value,
        subtotalCents: subtotalCents,
        depositPercent: depositPercent,
        createdAt: new Date().toISOString(),
        items: state.items,
      };
      await postAction({ action: "saveQuote", quote: quote });
      state.quotes.unshift(quote);
      state.saved = true;
      renderHistoryTab();
      toast("Orçamento salvo. Agora você pode imprimir ou enviar.", "success");
    } catch(e){
      toast((e && e.message) || "Não foi possível salvar.", "error");
    } finally {
      state.saving = false;
      updateSaveButtonState();
    }
  }

  function messageText(){
    var customerName = $("input-customer-name").value || "cliente";
    var subtotalCents = currentSubtotalCents();
    var depositPercent = Number(state.settings.deposit_percent || 50);
    var depositCents = Math.round(subtotalCents * depositPercent / 100);
    var validityDays = Number(state.settings.validity_days || 5);
    var validUntil = addDaysISO(validityDays);
    var lines = [
      "Olá, " + customerName + "! Segue o orçamento " + state.currentNumber + " da Panificadora Dreon:",
      "",
    ].concat(state.items.map(function(item){
      return "• " + quantityLabel(item) + " — " + item.productName + ": " + money.format(item.totalCents / 100);
    })).concat([
      "",
      "Total: " + money.format(subtotalCents / 100),
      "Sinal de " + depositPercent + "%: " + money.format(depositCents / 100),
      "Válido até " + formatDateBR(validUntil) + ".",
      "",
      state.settings.payment_note || "",
    ]);
    return lines.filter(function(line){ return line !== null && line !== undefined; }).join("\n");
  }

  function copyMessage(){
    navigator.clipboard.writeText(messageText()).then(function(){
      toast("Mensagem copiada para enviar ao cliente.", "success");
    }).catch(function(){
      toast("Não foi possível copiar a mensagem.", "error");
    });
  }

  function openWhatsApp(){
    var digits = ($("input-customer-phone").value || "").replace(/\D/g, "");
    var recipient = digits ? (digits.indexOf("55") === 0 ? digits : "55" + digits) : "";
    window.open("https://wa.me/" + recipient + "?text=" + encodeURIComponent(messageText()), "_blank", "noopener,noreferrer");
  }

  // ------------------------------------------------------------------
  // Histórico
  // ------------------------------------------------------------------

  function renderHistoryTab(){
    $("history-count").textContent = state.quotes.length + (state.quotes.length === 1 ? " orçamento" : " orçamentos");
    var wrap = $("history-wrap");
    if(!state.quotes.length){
      wrap.innerHTML = '<div class="empty-state">' +
        '<div class="empty-icon">🕘</div>' +
        '<h3 class="empty-title">Nenhum orçamento salvo</h3>' +
        '<p class="empty-text">Os orçamentos concluídos aparecerão aqui para consulta e reaproveitamento.</p>' +
      '</div>';
      return;
    }
    var rows = state.quotes.map(function(q){
      return '<tr>' +
        '<td class="mono">' + escapeHTML(q.quoteNumber) + '</td>' +
        '<td><div class="cell-strong">' + escapeHTML(q.customerName) + '</div><div class="cell-sub">' + escapeHTML(q.customerPhone || "Sem telefone") + '</div></td>' +
        '<td>' + (q.eventDate ? escapeHTML(formatDateBR(q.eventDate)) : "-") + '</td>' +
        '<td>' + escapeHTML(formatDateBR(q.validUntil)) + '</td>' +
        '<td class="ta-right cell-strong">' + escapeHTML(money.format(q.subtotalCents / 100)) + '</td>' +
        '<td class="ta-right"><button class="btn btn-outline btn-sm" onclick="app.duplicateQuote(\'' + q.id + '\')">📄 Duplicar</button></td>' +
      '</tr>';
    }).join("");
    wrap.innerHTML = '<div class="table-wrap"><table><thead><tr>' +
      '<th>Número</th><th>Cliente</th><th>Evento</th><th>Validade</th><th class="ta-right">Total</th><th class="ta-right">Ação</th>' +
      '</tr></thead><tbody>' + rows + '</tbody></table></div>';
  }

  function duplicateQuote(id){
    var quote = state.quotes.find(function(q){ return q.id === id; });
    if(!quote) return;
    $("input-customer-name").value = quote.customerName;
    $("input-customer-phone").value = quote.customerPhone;
    $("input-event-date").value = quote.eventDate || "";
    $("input-notes").value = quote.notes || "";
    state.items = quote.items.map(function(item){ return Object.assign({}, item, { id: makeId() }); });
    state.currentNumber = quoteNumber(state.quotes.length);
    state.saved = false;
    switchTab("quote");
    renderQuoteRight();
    toast("Orçamento duplicado. Revise os dados e salve como novo.", "success");
  }

  // ------------------------------------------------------------------
  // Produtos
  // ------------------------------------------------------------------

  function renderProductsTab(){
    var wrap = $("products-wrap");
    if(!state.products.length){
      wrap.innerHTML = '<div class="empty-state">' +
        '<div class="empty-icon">🏬</div>' +
        '<h3 class="empty-title">Nenhum produto cadastrado</h3>' +
        '<p class="empty-text">Cadastre o primeiro item do cardápio para começar a montar orçamentos.</p>' +
      '</div>';
      return;
    }
    var rows = state.products.map(function(p){
      var unitLabel = p.unit === "cento" ? "Por cento" : (p.unit === "kg" ? "Por kg" : "Por unidade");
      return '<tr class="' + (p.active ? "" : "row-muted") + '">' +
        '<td class="mono">' + escapeHTML(p.code) + '</td>' +
        '<td><div class="cell-strong">' + escapeHTML(p.name) + '</div>' +
          (p.description ? '<div class="cell-sub">' + escapeHTML(p.description) + '</div>' : "") + '</td>' +
        '<td>' + escapeHTML(p.category) + '</td>' +
        '<td>' + unitLabel + '</td>' +
        '<td class="cell-strong">' + escapeHTML(money.format(p.priceCents / 100)) + '</td>' +
        '<td><span class="badge ' + (p.active ? "badge-success" : "") + '">' + (p.active ? "Ativo" : "Inativo") + '</span></td>' +
        '<td class="ta-right">' +
          '<button class="icon-btn" title="Editar" onclick="app.openProductDialog(' + p.id + ')">✎</button> ' +
          '<button class="btn btn-ghost btn-sm" onclick="app.toggleProduct(' + p.id + ')">' + (p.active ? "Desativar" : "Reativar") + '</button>' +
        '</td>' +
      '</tr>';
    }).join("");
    wrap.innerHTML = '<div class="table-wrap"><table><thead><tr>' +
      '<th>Cód.</th><th>Produto</th><th>Categoria</th><th>Venda</th><th>Preço</th><th>Status</th><th class="ta-right">Ações</th>' +
      '</tr></thead><tbody>' + rows + '</tbody></table></div>';
  }

  async function toggleProduct(id){
    var product = state.products.find(function(p){ return p.id === id; });
    if(!product) return;
    try {
      await postAction({ action: "toggleProduct", id: product.id, active: !product.active });
      product.active = !product.active;
      renderProductsTab();
      toast(product.active ? "Produto reativado." : "Produto desativado.", "success");
    } catch(e){
      toast((e && e.message) || "Não foi possível alterar o produto.", "error");
    }
  }

  function openProductDialog(id){
    var product = id ? state.products.find(function(p){ return p.id === id; }) : null;
    state.editingProductId = product ? product.id : null;
    $("product-dialog-title").textContent = product ? "Editar produto" : "Novo produto";
    $("pf-code").value = product ? product.code : "";
    $("pf-category").value = product ? product.category : "Bolos";
    $("pf-name").value = product ? product.name : "";
    $("pf-unit").value = product ? product.unit : "kg";
    $("pf-price").value = product ? (product.priceCents / 100).toFixed(2).replace(".", ",") : "";
    $("pf-min-qty").value = product ? product.minimumQuantity : 0;
    $("pf-min-qty-label").textContent = (product ? product.unit : "kg") === "kg" ? "Quantidade mínima (kg)" : "Quantidade mínima (unidades)";
    $("pf-description").value = product ? product.description : "";
    $("product-dialog").showModal();
  }

  async function saveProductDialog(){
    var name = $("pf-name").value.trim();
    var category = $("pf-category").value.trim();
    var priceReais = $("pf-price").value.replace(",", ".");
    var priceCents = Math.round(Number(priceReais) * 100) || 0;
    if(!name || !category || !priceCents){
      toast("Preencha nome, categoria e preço.", "error");
      return;
    }
    var product = {
      id: state.editingProductId || undefined,
      code: $("pf-code").value,
      category: category,
      name: name,
      unit: $("pf-unit").value,
      priceCents: priceCents,
      minimumQuantity: Number($("pf-min-qty").value) || 0,
      description: $("pf-description").value,
    };
    var btn = $("btn-save-product");
    btn.disabled = true;
    btn.textContent = "Salvando...";
    try {
      await postAction({ action: "saveProduct", product: product });
      $("product-dialog").close();
      toast(state.editingProductId ? "Produto atualizado." : "Produto adicionado.", "success");
      await loadData();
    } catch(e){
      toast((e && e.message) || "Não foi possível salvar.", "error");
    } finally {
      btn.disabled = false;
      btn.textContent = "💾 Salvar produto";
    }
  }

  // ------------------------------------------------------------------
  // Configurações
  // ------------------------------------------------------------------

  async function saveSettings(){
    var keys = ["company_name","trade_name","cnpj","phone","email","address","validity_days","deposit_percent","lead_time_days","payment_note"];
    var settings = {};
    keys.forEach(function(key){ settings[key] = $("set-" + key).value; });
    var btn = $("btn-save-settings");
    btn.disabled = true;
    btn.textContent = "Salvando...";
    try {
      await postAction({ action: "saveSettings", settings: settings });
      state.settings = settings;
      applySettingsToForm();
      renderQuoteRight();
      toast("Dados da empresa atualizados.", "success");
    } catch(e){
      toast((e && e.message) || "Não foi possível salvar.", "error");
    } finally {
      btn.disabled = false;
      btn.textContent = "💾 Salvar alterações";
    }
  }

  // ------------------------------------------------------------------
  // Wiring inicial
  // ------------------------------------------------------------------

  document.addEventListener("DOMContentLoaded", function(){
    ["input-customer-name", "input-customer-phone", "input-event-date", "input-notes"].forEach(function(id){
      $(id).addEventListener("input", function(){ markChanged(); buildPreviewHTML(); });
    });
    $("input-quantity").addEventListener("keydown", function(e){
      if(e.key === "Enter"){ e.preventDefault(); addItem(); }
    });
    $("product-search").addEventListener("input", onProductSearchInput);
    $("product-search").addEventListener("focus", onProductSearchInput);
    document.addEventListener("click", function(e){
      if(!e.target.closest("#product-combobox")) closeDropdown();
    });
    loadData();
  });

  window.app = {
    switchTab: switchTab,
    addItem: addItem,
    removeItem: removeItem,
    selectProductOption: selectProductOption,
    saveQuote: saveQuote,
    resetQuote: resetQuote,
    copyMessage: copyMessage,
    openWhatsApp: openWhatsApp,
    duplicateQuote: duplicateQuote,
    openProductDialog: openProductDialog,
    saveProductDialog: saveProductDialog,
    toggleProduct: toggleProduct,
    saveSettings: saveSettings,
  };
})();

'''


# ---------------------------------------------------------------------------
# Servidor HTTP (biblioteca padrão apenas — sem Flask, sem dependências)
# ---------------------------------------------------------------------------

_RENDERED_HTML = None


def rendered_html():
    global _RENDERED_HTML
    if _RENDERED_HTML is None:
        _RENDERED_HTML = INDEX_HTML.replace("", LOGO_BASE64).replace("__APP_JS__", APP_JS)
    return _RENDERED_HTML


class Handler(BaseHTTPRequestHandler):
    server_version = "OrcamentosDreon/1.0"

    def log_message(self, fmt, *args):
        sys.stderr.write("%s - - [%s] %s\n" % (self.address_string(), self.log_date_time_string(), fmt % args))

    def _send_json(self, payload, status=200):
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def _send_html(self, html, status=200):
        body = html.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        path = urlparse(self.path).path
        try:
            if path == "/" or path == "/index.html":
                self._send_html(rendered_html())
            elif path == "/api/data":
                data = with_db(handle_get_data)
                self._send_json(data)
            elif path == "/health":
                self._send_json({"ok": True, "service": "orcamentos-dreon"})
            else:
                self._send_json({"error": "Não encontrado."}, status=404)
        except Exception as error:  # noqa: BLE001
            print(f"Falha ao carregar dados: {error}", file=sys.stderr)
            self._send_json({"error": "Não foi possível carregar os dados agora."}, status=500)

    def do_POST(self):
        path = urlparse(self.path).path
        if path != "/api/data":
            self._send_json({"error": "Não encontrado."}, status=404)
            return
        try:
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b"{}"
            body = json.loads(raw.decode("utf-8") or "{}")
        except Exception:
            self._send_json({"error": "Requisição inválida."}, status=400)
            return

        try:
            result = with_db(lambda conn: handle_post_action(conn, body))
            self._send_json(result)
        except ApiError as error:
            self._send_json({"error": error.message}, status=error.status)
        except Exception as error:  # noqa: BLE001
            print(f"Falha ao salvar dados: {error}", file=sys.stderr)
            self._send_json({"error": "Não foi possível salvar agora."}, status=500)


def main():
    with_db(lambda conn: None)  # garante schema + seed antes de aceitar requisições
    server = ThreadingHTTPServer((HOST, PORT), Handler)
    print(f"Orçamentos Dreon rodando em http://{HOST}:{PORT}/  (banco: {DATABASE_PATH})")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nEncerrando…")
        server.shutdown()


if __name__ == "__main__":
    main()
